use core::{borrow::Borrow, marker::PhantomData};

use crate::{
    expectation::{AssertionContext, Evidence, Expectation, MatcherList, composite_items},
    failure::{FailureBuilder, FailureKind, PathSegment},
};

/// A matcher generated by `partial!` for selected fields and enum variants.
/// Its representation is unsupported.
pub struct PartialMatch<A: ?Sized, P, L> {
    shape: P,
    fields: L,
    name: &'static str,
    variant: Option<&'static str>,
    actual: PhantomData<fn(&A)>,
}

/// Constructor behind `partial!` structure matching.
pub fn partial_match<A: ?Sized, P, L>(
    shape: P,
    fields: L,
    name: &'static str,
    variant: Option<&'static str>,
) -> PartialMatch<A, P, L>
where
    P: Fn(&A) -> bool,
{
    PartialMatch {
        shape,
        fields,
        name,
        variant,
        actual: PhantomData,
    }
}

/// The pattern fixes the matched type `A`. Any subject borrowing an `A` can be matched, so the
/// same matcher checks a `User`, a `&User`, or a `Box<User>` without `dereferenced`.
impl<S, A, R, F, L> Expectation<S, R> for PartialMatch<A, F, L>
where
    S: Borrow<A> + ?Sized,
    A: ?Sized,
    F: Fn(&A) -> bool,
    L: MatcherList<A, R>,
{
    composite_items!(S);

    fn evaluate(&self, actual: &S, settings: &AssertionContext<'_, R>) -> Result<(), Evidence> {
        let actual: &A = actual.borrow();
        let mut context = settings.isolated();
        // A wrong shape skips the fields. The subject itself is rejected, so the evidence has no
        // variant path. Rendering the subject would need a renderer the pattern does not require,
        // so `showing_actual` adds it on request.
        if !(self.shape)(actual) {
            context.record(|_| {
                FailureBuilder::new::<A>(FailureKind::Variant)
                    .relation("is not the expected variant")
                    .expected(self.name)
                    .build()
            });
            return Err(context.into_evidence());
        }
        // The structural fallback stays within the variant scope, so a rejection always leaves
        // evidence there.
        let evaluate = |context: &mut AssertionContext<'_, R>| {
            let mut matched = true;
            for index in 0..self.fields.len() {
                matched &= self.fields.evaluate_at(index, actual, context);
            }
            context.complete(matched, |_| {
                FailureBuilder::new::<()>(FailureKind::Matching)
                    .relation("has the required structure")
                    .expected(self.name)
                    .build()
            })
        };
        let matched = if let Some(variant) = self.variant {
            context.scoped(PathSegment::Variant(variant), evaluate)
        } else {
            evaluate(&mut context)
        };
        if matched {
            Ok(())
        } else {
            Err(context.into_evidence())
        }
    }

    const KIND: FailureKind = FailureKind::Matching;

    fn explain(
        &self,
        rejected: Option<(&S, Evidence)>,
        failure: FailureBuilder,
        context: &AssertionContext<'_, R>,
    ) -> FailureBuilder {
        match rejected {
            None => context.describe_list::<A, _>(
                &self.fields,
                failure
                    .path(self.variant.map(PathSegment::Variant))
                    .relation("has the required structure")
                    .expected(self.name),
            ),
            Some((_, evidence)) => failure.relation("does not match").evidence(evidence),
        }
    }
}

#[cfg(test)]
mod tests {
    use core::cell::Cell;

    use super::partial_match;
    use crate::{
        __private::field,
        assertions::{collection::elements_are_in_any_order, core::partial_eq::eq},
        failure::{FailureKind, PathSegment},
        prelude::*,
        test_support::{NoRenderer, opaque_predicate},
    };

    #[test]
    fn missing_subject_descriptions_preserve_nested_field_and_variant_paths() {
        let matcher = field(
            |row: &((i32,),)| Some(&row.0),
            partial_match(
                |_: &(i32,)| true,
                crate::matchers![field(
                    |row: &(i32,)| Some(&row.0),
                    eq(2),
                    PathSegment::TupleIndex(0),
                )],
                "Choice::Some",
                Some("Some"),
            ),
            PathSegment::Field("choice"),
        );
        let actual: [((i32,),); 0] = [];
        let failures = assert_that!(actual)
            .capture(|it| it.matches(elements_are_in_any_order(matchers![matcher])));
        let description = failures[0].children[0].constraint.as_ref().unwrap();
        assert_that!(description.path)
            .is_equal_to([PathSegment::Field("choice"), PathSegment::Variant("Some")]);
        let field = &description.children[0];
        assert_that!(field.path).is_equal_to([PathSegment::TupleIndex(0)]);
        assert_that!(field.subject_type_name).is_equal_to("i32");
        assert_that!(field.kind).is_equal_to(FailureKind::Equality);
        assert_that!(field.relation.as_deref()).is_equal_to(Some("is equal to"));
    }

    #[test]
    #[cfg(feature = "partial")]
    fn missing_partial_struct_descriptions_identify_each_selected_field() {
        struct Row {
            age: i32,
            score: i32,
        }
        let actual: [Row; 0] = [];
        let failures = assert_that!(actual).capture(|it| {
            it.matches(crate::elements_are_in_any_order![crate::partial!(Row {
                age: eq(1),
                score: eq(2)
            })])
        });
        let description = failures[0].children[0].constraint.as_ref().unwrap();
        assert_that!(description.children).has_length(2);
        for (child, name) in description.children.iter().zip(["age", "score"]) {
            assert_that!(child.path).is_equal_to([PathSegment::Field(name)]);
            assert_that!(child.kind).is_equal_to(FailureKind::Equality);
        }
    }

    #[test]
    fn wrong_shapes_skip_fields_and_reject_the_subject() {
        let calls = Cell::new(0);
        let matcher = partial_match(
            Option::is_some,
            crate::matchers![opaque_predicate(|_: &Option<i32>| {
                calls.set(calls.get() + 1);
                true
            })],
            "Option::Some",
            Some("Some"),
        );
        let failures = assert_that!(None::<i32>)
            .with_renderer(NoRenderer)
            .capture(|it| it.matches(&matcher));

        assert_that!(calls.get()).is_equal_to(0);
        assert_that!(failures[0].children[0].path).is_empty();
        assert_that!(failures[0].children[0].kind).is_equal_to(FailureKind::Variant);

        assert_that!(Some(1))
            .with_renderer(NoRenderer)
            .matches(&matcher);
        assert_that!(calls.get()).is_equal_to(1);
    }
    #[test]
    fn borrowing_subjects_are_matched_as_the_pattern_type() {
        let matcher = partial_match(
            Option::is_some,
            crate::matchers![field(
                |value: &Option<i32>| value.as_ref(),
                eq(1),
                PathSegment::TupleIndex(0),
            )],
            "Option::Some",
            Some("Some"),
        );
        let value = Some(1);
        assert_that_owned!(&value).matches(&matcher);
        assert_that!(Box::new(value)).matches(&matcher);

        let failures = assert_that_owned!(&None::<i32>).capture(|it| it.matches(&matcher));
        assert_that!(failures[0].children[0].relation.as_deref())
            .is_equal_to(Some("is not the expected variant"));
    }
    #[test]
    #[cfg(feature = "partial")]
    fn mismatched_variants_name_the_expected_variant() {
        assert_that!(|| {
            assert_that!(Err::<i32, &str>("timed out"))
                .with_location(false)
                .matches(crate::partial!(variant Ok(eq(1))));
        })
        .panics()
        .message()
        .is_equal_to(indoc::indoc! {r#"
            -------- assertr --------
            Expression: `Err::<i32, &str>("timed out")`

            does not match

            Nested failures:
              - is not the expected variant

                Expected: Ok
            -------- assertr --------
        "#});
    }

    #[test]
    #[cfg(feature = "partial")]
    fn showing_actual_renders_the_mismatched_subject() {
        let failures = assert_that!(Err::<i32, &str>("timed out")).capture(|it| {
            it.matches(matchers::showing_actual(crate::partial!(
                variant Ok(eq(1))
            )))
        });
        assert_that!(failures[0].to_string()).contains("Actual: Err(\n    \"timed out\",\n)");
    }
}
